You're reviewing this service worker code generated by an LLM. List every anti-pattern you find and explain the consequence of each:

```js
self.addEventListener('install', (e) => {
  self.skipWaiting();
  e.waitUntil(
    caches.open('app-cache').then(cache =>
      cache.addAll(['/index.html', '/app.js', '/style.css', '/logo.png',
        '/about.html', '/contact.html', '/images/hero.jpg',
        '/images/team.jpg', '/fonts/inter.woff2'])
    )
  );
});

self.addEventListener('fetch', (e) => {
  e.respondWith(
    caches.match(e.request).then(r => r || fetch(e.request)
      .then(res => {
        caches.open('app-cache').then(c => c.put(e.request, res.clone()));
        return res;
      })
    ).catch(() => caches.match('/index.html'))
  );
});
```
